import{_ as o,l,o as e,c as i,v as t,p as n,x as s,d as m,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"贝尔曼方程","description":"","frontmatter":{"title":"贝尔曼方程","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bellman-dp.md","filePath":"econ/bellman-dp.md","lastUpdated":1789023840000}'),d={name:"econ/bellman-dp.md"};function h(_,a,u,B,E,b){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="贝尔曼方程" tabindex="-1">贝尔曼方程 <a class="header-anchor" href="#贝尔曼方程" aria-label="Permalink to &quot;贝尔曼方程&quot;">​</a></h1><div class="epigraph"><p>最优值是今天的回报加上贴现后的续值；状态足够时，序列问题塌成函数方程。</p><footer>—— Bellman, Dynamic Programming, 1957；Stokey and Lucas with Prescott, Recursive Methods in Economic Dynamics, 1989</footer></div><p><a href="/econ/multi-period-consumption-portfolio">上一课</a>在离散多期里已经用贝尔曼写消费与组合，并声明：动态宏观的求解装置从这里交接，不再从零讲两基金。本课缺口是把那条装置从组合菜单里抽出来，写成<strong>一般递归</strong>：状态、控制、转移、值函数。后课默认已经有这条方程，不再每次从 Ramsey 序列重写。不重解 HJB，不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Samuelson 的 \\(V_t(W)\\) 是财富上的贝尔曼，状态几乎是标量。宏观一旦有资本、劳动、外生冲击，序列问题是 \\(\\max\\mathrm{E}\\sum_t\\beta^t u(c_t)\\) 受资源与技术约束，直接写无穷序列既难算也难看清政策是状态的函数。Bellman：在正则条件下</p> \\[V(s)=\\max_{a\\in\\Gamma(s)}\\Bigl\\{r(s,a)+\\beta\\mathrm{E}\\bigl[V(s&#39;)\\bigm|s,a\\bigr]\\Bigr\\}, \\]<p>\\(s\\) 为状态，\\(a\\) 为控制，\\(\\Gamma\\) 为可行集，\\(r\\) 为当期回报。缺口不是再推消费欧拉，而是：动态宏观的对象是这个函数方程的解 \\(V\\) 与政策 \\(a=g(s)\\)，不是一条事先写死的时间路径。</p><p><span class="marginnote">Stokey–Lucas–Prescott 把压缩映射、单调性、凹性写成宏观可用的许可证。Blackwell 充分条件保证 \\(T\\) 是折扣压缩。本课用它们，不重写泛函分析。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先选状态：凡是影响可行集或回报、且按已知转移走的变量都进 \\(s\\)。代表性 Ramsey：\\(s=k\\)，冲击经济再加 \\(z\\)。控制是 \\(c\\) 或投资。算子 \\(T(V)(s)=\\max_a\\{r+\\beta\\mathrm{E}V&#39;\\}\\)。\\(\\beta\\lt 1\\)、\\(r\\) 有界时 \\(T\\) 在有界连续函数上是压缩，唯一不动点即值函数；凹性与单调性可从原问题继承到 \\(V\\)。确定性下包络给出欧拉；随机下给出随机欧拉。横截与泡沫下一课才钉。</p>',10)),(e(),n(c,null,{default:s(()=>[p(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%BA%8F%E5%88%97%E9%97%AE%E9%A2%98%22%5D%20--%3E%20ST%5B%22%E9%80%89%E7%8A%B6%E6%80%81%20s%22%5D%0A%20%20ST%20--%3E%20BE%5B%22V%20%3D%20T(V)%22%5D%0A%20%20BE%20--%3E%20POL%5B%22%E6%94%BF%E7%AD%96%20a%20%3D%20g(s)%22%5D%0A%20%20POL%20--%3E%20PATH%5B%22%E6%B2%BF%E8%BD%AC%E7%A7%BB%E8%B5%B0%E5%87%BA%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与上一课的分工：组合课已经示范 \\(V(W)\\)；本课示范同一算子如何接到资本与总量约束。资产菜单若再出现，只引用欧拉的资产形式，不重写短视定理。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是<strong>状态充分统计</strong>。昨天的决策只通过今天的 \\(s\\) 影响明天，历史不必进自变量。政策因此是函数 \\(g\\)，加总与估计才能写成递归均衡：价格是 \\(s\\) 的函数，家庭的 \\(V\\) 把价格函数当给定，再出清。代表性个体时 \\(s\\) 是总量；异质时个人状态与分布一起走——那是 <a href="/econ/bewley-aiyagari">Bewley</a> 的缺口，本课先把算子立住。</p><p>时间不一致已经在主干出现过：若未来自己会再优化且与今天目标冲突，\\(V\\) 的递归要改成博弈。本课程默认标准贴现效用，承诺问题另接。连续时间 HJB 是同一递归的扩散写法，本栏不重推伊藤。</p><p><span class="marginnote">Lucas 树的 \\(p(y)\\) 也是递归：价格是果实状态的函数。本课不重写树，只提醒：定价函数与值函数是同一装置的两个实例。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给算法（下一课 VFI/PI），不把欧拉当唯一一阶条件（再下一课才把横截补上）。也不把贝尔曼写成「宏观就是动态规划」的口号：没有正确的状态，方程是错的；没有压缩或有界性，唯一性不必有。无限维分布作为状态时，压缩论证更脆，留给 Krusell–Smith。</p><p>后课默认：动态宏观先写 \\(V=T(V)\\) 与 \\(g(s)\\)；序列形式只在需要横截或变分时展开。组合短视、两基金、FTAP 已经在上一课程结束，本栏不重写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贝尔曼把序列问题收成状态上的函数方程；\\(V\\) 与政策 \\(g\\) 是后课的公共对象。</li><li>状态必须充分；算子在折扣与有界回报下常是压缩。</li><li>本课从组合贝尔曼交接，不再讲菜单。</li><li>出处：Bellman 1957；Stokey, Lucas and Prescott, <em>Recursive Methods</em>, 1989。</li></ul>',10))])}const V=o(d,[["render",h]]);export{g as __pageData,V as default};
